const start = slotStartTime.hour() * 60 + slotStartTime.minute();
const end = start + eventLength;
const isWithinWorkingHours = workingHours.some(
  (wh) => wh.days.includes(slotStartTime.day()) && start >= wh.startTime && end <= wh.endTime
);
if (!isWithinWorkingHours) {
  return true;
}

r.log.Debug("Annotations to clean by time", "count", len(ids), "ids", ids, "cond", cond)

x, y := r.deleteByIDs(ctx, "annotation", ids)
if y != nil {
	r.log.Error("failed to clean annotations by time", "count", len(ids), "affected", x, "err", y)
} else {
	r.log.Debug("cleaned annotations by time", "count", len(ids), "affected", x)
}

const cell = renderTableBodyCell?.(column, dataRow, rowIndex, columnIndex);
if (cell !== undefined) {
  return cell;
}

def close(self) -> None:
    # Drain workers first so all in-flight offsets are marked complete
    self.queue_pool.shutdown()
    self.shutdown_event.set()
    self.commit_thread.join(timeout=5.0)

    # Final commit of anything that completed after the last loop iteration
    try:
        committable = self.queue_pool.offset_tracker.get_committable_offsets()
        if committable:
            self.commit_function(committable)
            for partition, offset in committable.items():
                self.queue_pool.offset_tracker.mark_committed(partition, offset)
    except Exception:
        logger.exception("Error in final commit during close")
